  INSERT INTO public.destination_link_translations (link_id, locale, url, active)
  SELECT l.id, v.locale, v.url, true
  FROM variants v
  JOIN public.destination_links l ON l.url = v.source_url
  JOIN public.destinations d ON d.id = l.destination_id
  WHERE l.kind IN ('DISCOVER', 'WEBSITE') AND l.active AND d.active
  ON CONFLICT (link_id, locale) DO NOTHING
  RETURNING link_id
)
INSERT INTO public.site_link_translations (setting_key, locale, url, active)
SELECT s.key, v.locale, v.url, true
FROM variants v JOIN public.site_settings s ON s.value = v.source_url
WHERE s.key = 'website'
ON CONFLICT (setting_key, locale) DO NOTHING;
COMMIT;
